-- Server-issued questions; only received answers, never caller-supplied scores, earn ranked credit.
create table if not exists public.adjective_question_bank (
 question_key text primary key,
 params jsonb not null,
 answers jsonb not null,
 active boolean not null default true
);
create table if not exists public.adjective_issued_questions (
 run_id uuid not null references public.adjective_drill_runs(id) on delete cascade,
 ordinal smallint not null check(ordinal between 0 and 149),
 question_key text not null references public.adjective_question_bank(question_key),
 answered_at timestamptz,
 submitted jsonb,
 correct boolean,
 primary key(run_id,ordinal)
);
alter table public.adjective_question_bank enable row level security;
alter table public.adjective_issued_questions enable row level security;
revoke all on public.adjective_question_bank,public.adjective_issued_questions from public,anon,authenticated;
alter table public.adjective_drill_runs add column if not exists verified boolean not null default false;

create or replace function public.start_verified_adjective_run()
returns jsonb language plpgsql security definer set search_path=public as $$
declare rid uuid; i integer; qkey text; nouns text[]; questions jsonb;
begin
 if auth.uid() is null or not public.is_active_user() then raise exception 'not authorized' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,915));
 if not exists(select 1 from public.adjective_question_bank where active) then raise exception 'question bank unavailable'; end if;
 rid:=public.start_adjective_run();
 select array_agg(noun) into nouns from (select noun from (select distinct params->'noun'->>'id' as noun from public.adjective_question_bank where active) n order by random() limit 10) chosen;
 for i in 0..149 loop
   select question_key into qkey from public.adjective_question_bank where active and params->'noun'->>'id'=any(nouns) order by random() limit 1;
 end loop;
 select jsonb_agg(jsonb_build_object('ordinal',q.ordinal,'params',b.params) order by q.ordinal) into questions
 from public.adjective_issued_questions q join public.adjective_question_bank b using(question_key) where q.run_id=rid;
 return jsonb_build_object('id',rid,'questions',questions,'startedAt',now(),'durationMs',300000);
end $$;

create or replace function public.answer_verified_adjective(p_run uuid,p_ordinal integer,p_answers jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.adjective_drill_runs%rowtype; q public.adjective_issued_questions%rowtype; expected jsonb; ok boolean;
begin
 if auth.uid() is null or not public.is_active_user() then raise exception 'not authorized' using errcode='42501'; end if;
 select * into r from public.adjective_drill_runs where id=p_run and user_id=auth.uid() for update;
 if not found then raise exception 'run not found' using errcode='42501'; end if;
 select * into q from public.adjective_issued_questions where run_id=p_run and ordinal=p_ordinal for update;
 if not found then raise exception 'question not issued' using errcode='22023'; end if;
 if q.answered_at is not null then
   if q.submitted=p_answers then return jsonb_build_object('accepted',true,'correct',q.correct); end if;
   raise exception 'question already answered' using errcode='22023';
 end if;
 if r.finished_at is not null or clock_timestamp()-r.started_at > interval '305 seconds' then raise exception 'answer window closed' using errcode='22023'; end if;
 if p_answers is null or jsonb_typeof(p_answers)<>'object' or octet_length(p_answers::text)>256 then raise exception 'invalid answers' using errcode='22023'; end if;
 select answers into expected from public.adjective_question_bank where question_key=q.question_key;
 ok:=coalesce(p_answers->'article','null'::jsonb)=expected->'article'
   and coalesce(p_answers->'adjective','null'::jsonb)=expected->'adjective'
   and coalesce(p_answers->'noun','null'::jsonb)=expected->'noun';
 update public.adjective_issued_questions set submitted=p_answers,correct=ok,answered_at=clock_timestamp() where run_id=p_run and ordinal=p_ordinal;
 return jsonb_build_object('accepted',true,'correct',ok);
end $$;

create or replace function public.finish_verified_adjective_run(p_id uuid)
returns table(score integer,answered integer) language plpgsql security definer set search_path=public as $$
declare r public.adjective_drill_runs%rowtype; points integer; attempts integer;
begin
 if auth.uid() is null or not public.is_active_user() then raise exception 'not authorized' using errcode='42501'; end if;
 select * into r from public.adjective_drill_runs where id=p_id and user_id=auth.uid() for update;
 if not found then raise exception 'run not found' using errcode='42501'; end if;
 if not exists(select 1 from public.adjective_issued_questions where run_id=p_id) then raise exception 'unverified legacy run' using errcode='22023'; end if;
 if r.verified and r.finished_at is not null then return query select r.score,r.answered; return; end if;
 if now()-r.started_at<interval '295 seconds' then raise exception 'finished too early' using errcode='22023'; end if;
 if now()-r.started_at>interval '24 hours' then raise exception 'too late to finish' using errcode='22023'; end if;
 select count(*) filter(where correct),count(*) filter(where answered_at is not null) into points,attempts
 from public.adjective_issued_questions where run_id=p_id;
 update public.adjective_drill_runs set score=points,answered=attempts,verified=true,finished_at=now() where id=p_id;
 return query select points,attempts;
end $$;
revoke all on function public.start_verified_adjective_run() from public,anon;
revoke all on function public.answer_verified_adjective(uuid,integer,jsonb) from public,anon;
revoke all on function public.finish_verified_adjective_run(uuid) from public,anon;
grant execute on function public.start_verified_adjective_run() to authenticated;
grant execute on function public.answer_verified_adjective(uuid,integer,jsonb) to authenticated;
grant execute on function public.finish_verified_adjective_run(uuid) to authenticated;

create or replace function public.get_verified_adjective_board(p_period text default 'all', p_limit integer default 100)
returns table (
  user_id      uuid,
  display_name text,
  avatar_url   text,
  best         integer,
  top3         integer[],
  best_at      timestamptz,
  rank         bigint,
  is_me        boolean
)
language sql
stable
security definer
set search_path = public
as $$
  with scoped as (
    select r.user_id, r.score, r.finished_at
    from public.adjective_drill_runs r
    where r.finished_at is not null and r.verified
      and (p_period <> 'week' or r.finished_at >= now() - interval '7 days')
  ),
  per_user as (
    select s.user_id, max(s.score) as best
    from scoped s
    group by s.user_id
  ),
  best_runs as (
    select pu.user_id, min(s.finished_at) as best_at
    from per_user pu
    join scoped s on s.user_id = pu.user_id and s.score = pu.best
    group by pu.user_id
  ),
  top3s as (
    select x.user_id, array_agg(x.score order by x.score desc) as top3
    from (
      select s.user_id, s.score, row_number() over (partition by s.user_id order by s.score desc) as rn
      from scoped s
    ) x
    where x.rn <= 3
    group by x.user_id
  ),
  board as (
    select p.id                        as user_id,
           p.display_name,
           p.avatar_url,
           pu.best                     as best,
           t.top3                      as top3,
           br.best_at                  as best_at,
           (p.id = auth.uid())         as is_me,
           p.show_on_leaderboard       as visible
    from public.profiles p
    join per_user pu   on pu.user_id = p.id
    join best_runs br   on br.user_id = p.id
    join top3s t         on t.user_id = p.id
    where p.suspended_at is null
      and (p.show_on_leaderboard or p.id = auth.uid())
  ),
  ranked as (
    select b.*, rank() over (order by b.best desc, b.best_at asc) as rank
    from board b
    where b.visible
    union all
    select b.*, 1 + (
      select count(*) from board v
      where v.visible and (v.best > b.best or (v.best = b.best and v.best_at < b.best_at))
    ) as rank
    from board b
    where not b.visible
  )
  select r.user_id, r.display_name, r.avatar_url, r.best, r.top3, r.best_at, r.rank, r.is_me
  from ranked r
  where r.rank <= greatest(1, least(p_limit, 500)) or r.is_me
  order by r.rank, r.is_me desc, r.display_name;
$$;
revoke all on function public.get_verified_adjective_board(text,integer) from public,anon;
grant execute on function public.get_verified_adjective_board(text,integer) to authenticated;

create or replace function public.get_my_verified_adjective_bests()
returns table (best_all integer, best_week integer)
language sql
stable
security definer
set search_path = public
as $$
  select
    (select max(score) from public.adjective_drill_runs where user_id = auth.uid() and finished_at is not null and verified),
    (select max(score) from public.adjective_drill_runs where user_id = auth.uid() and finished_at is not null and verified
       and finished_at >= now() - interval '7 days');
$$;
revoke all on function public.get_my_verified_adjective_bests() from public,anon;
grant execute on function public.get_my_verified_adjective_bests() to authenticated;

-- BEGIN GENERATED ADJECTIVE BANK
update public.adjective_question_bank set active=false;
on conflict(question_key) do update set active=true;
